'use client';

import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { TrendingUpIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { RESULTS, SECTION, type Result } from './data';
import { ScoreCard } from './score-card';

const ARRIVES_AFTER_MS = 500;

function formatOf(fractionDigits: number): Intl.NumberFormatOptions {
  return {
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  };
}

function shownOf(isRolled: boolean, value: number) {
  if (isRolled) {
    return value;
  }
  return 0;
}

type ResultItemProps = {
  result: Result;
  isRolled: boolean;
};

function ResultItem({ result, isRolled }: ResultItemProps) {
  return (
    <li className='bg-foreground/[0.05] flex min-w-0 flex-col gap-3 rounded-xl p-5'>
      <p className='flex'>
        <MotionNumber
          value={shownOf(isRolled, result.value)}
          format={formatOf(result.fractionDigits)}
          suffix={result.suffix}
          className='text-4xl font-semibold @2xl:text-5xl'
        />
      </p>
      <div className='flex flex-col gap-1'>
        <p className='text-[13px] font-medium'>{result.label}</p>
        <p className='text-muted-foreground text-xs text-pretty'>
          {result.compare}
        </p>
      </div>
    </li>
  );
}

export default function Stats02() {
  const [hasArrived, setHasArrived] = useState(false);
  const shouldReduceMotion = usePrefersReducedMotion();
  const steps = [{ after: ARRIVES_AFTER_MS, run: () => setHasArrived(true) }];
  const { ref, isAutoplaying, restart } = useAutoplay<HTMLElement>(steps, {
    onReset: () => setHasArrived(false),
  });
  const isTakenOver = !isAutoplaying;
  const isRolled = hasArrived || isTakenOver;
  const canReplay = isRolled && !shouldReduceMotion;

  return (
    <section
      ref={ref}
      className='dark bg-sidebar text-foreground @container w-full'
    >
      <div className='mx-auto flex max-w-6xl flex-col gap-12 px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <header className='flex flex-wrap items-center justify-between gap-x-4 gap-y-2'>
          <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
            <TrendingUpIcon className='size-4' />
            {SECTION.label}
          </p>
          <div className='flex items-center gap-2'>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
            <Badge variant='secondary'>Illustrative</Badge>
          </div>
        </header>
        <div className='grid items-center gap-12 @4xl:grid-cols-[minmax(0,1fr)_18rem]'>
          <div className='flex flex-col gap-10'>
            <h2 className='max-w-3xl text-3xl font-semibold text-balance @2xl:text-5xl'>
              {SECTION.mission}
            </h2>
            <ul className='grid gap-3 @2xl:grid-cols-3'>
              {RESULTS.map((result) => (
                <ResultItem
                  key={result.id}
                  result={result}
                  isRolled={isRolled}
                />
              ))}
            </ul>
            <p className='text-muted-foreground text-xs'>{SECTION.note}</p>
          </div>
          <ScoreCard isRolled={isRolled} />
        </div>
      </div>
    </section>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { Wash } from '@/registry/ndeko/ui/wash';

import { SCORE } from './data';
import { ScoreRing } from './score-ring';

const MAX_SCORE = 100;

type ScoreCardProps = {
  /** The score reads zero until the section has arrived, then rolls to its value as the ring closes. */
  isRolled: boolean;
};

function shownOf(isRolled: boolean) {
  if (isRolled) {
    return SCORE.value;
  }
  return 0;
}

export function ScoreCard({ isRolled }: ScoreCardProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const score = shownOf(isRolled);

  return (
    <article
      aria-label={`${SCORE.title}: ${SCORE.value} out of ${MAX_SCORE}`}
      className='surface-brand relative isolate mx-auto flex w-full max-w-72 -rotate-3 flex-col gap-5 rounded-2xl p-5 @4xl:mx-0'
    >
      <Wash shape='top' />
      <header className='flex items-baseline justify-between gap-3'>
        <h3 className='text-sm font-medium'>{SCORE.title}</h3>
        <p className='text-muted-foreground text-xs'>{SCORE.period}</p>
      </header>
      <div className='flex items-center gap-4'>
        <ScoreRing
          score={score}
          max={MAX_SCORE}
          shouldReduceMotion={shouldReduceMotion}
        >
          <span className='flex flex-col items-center leading-none'>
            <MotionNumber value={score} className='text-4xl font-semibold' />
            <span className='text-muted-foreground mt-1 text-[11px]'>
              out of {MAX_SCORE}
            </span>
          </span>
        </ScoreRing>
        <p className='text-muted-foreground text-xs text-pretty'>
          {SCORE.caption}
        </p>
      </div>
    </article>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

const VIEW = 120;

const CENTRE = VIEW / 2;

const RADIUS = 52;

const STROKE_WIDTH = 8;

const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

function openLengthOf(score: number, max: number) {
  const ratio = score / max;
  const atLeastNone = Math.max(0, ratio);
  const share = Math.min(1, atLeastNone);
  const open = 1 - share;
  return CIRCUMFERENCE * open;
}

function easedOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return 'transition-none';
  }
  return 'transition-[stroke-dashoffset] duration-[1100ms] ease-(--ease-out-strong)';
}

type ScoreRingProps = {
  score: number;
  max: number;
  shouldReduceMotion: boolean;
  className?: string;
  children?: React.ReactNode;
};

/** The stroke is the only thing that moves: it closes to its length once, as the score in the middle rolls. */
export function ScoreRing({
  score,
  max,
  shouldReduceMotion,
  className,
  children,
}: ScoreRingProps) {
  return (
    <span
      className={cn(
        'relative inline-flex size-32 shrink-0 items-center justify-center',
        className
      )}
    >
      <svg
        aria-hidden='true'
        viewBox={`0 0 ${VIEW} ${VIEW}`}
        className='absolute inset-0 size-full -rotate-90'
      >
        <circle
          cx={CENTRE}
          cy={CENTRE}
          r={RADIUS}
          fill='none'
          strokeWidth={STROKE_WIDTH}
          className='stroke-foreground/10'
        />
        <circle
          cx={CENTRE}
          cy={CENTRE}
          r={RADIUS}
          fill='none'
          strokeWidth={STROKE_WIDTH}
          strokeLinecap='round'
          strokeDasharray={CIRCUMFERENCE}
          strokeDashoffset={openLengthOf(score, max)}
          className={cn('stroke-primary', easedOf(shouldReduceMotion))}
        />
      </svg>
      {children}
    </span>
  );
}

export const SECTION = {
  label: 'Results',
  mission:
    'We write the first draft of every reply, so people spend their week on the judgment calls.',
  note: 'Every figure here is illustrative',
};

export type ResultId = 'handoff' | 'reply' | 'hours';

export type Result = {
  id: ResultId;
  value: number;
  fractionDigits: number;
  suffix: string;
  label: string;
  /** What the figure is measured against. A result without it would be a number floating in space. */
  compare: string;
};

export const RESULTS: Result[] = [
  {
    id: 'handoff',
    value: 62,
    fractionDigits: 0,
    suffix: '%',
    label: 'Fewer tickets handed over',
    compare: 'Compared with the quarter before the agents',
  },
  {
    id: 'reply',
    value: 3.4,
    fractionDigits: 1,
    suffix: '×',
    label: 'Faster first reply',
    compare: 'Compared with a queue answered only by people',
  },
  {
    id: 'hours',
    value: 38,
    fractionDigits: 0,
    suffix: ' h',
    label: 'Saved every week',
    compare: 'Compared with the hours spent drafting by hand',
  },
];

export const SCORE = {
  value: 87,
  title: 'Draft quality',
  period: 'Last 30 days',
  caption: 'Drafts sent as written, weighted by how much was edited',
};
